    """qos-check 的工作量预演：独立链路副本与空状态，无副作用。

    计费与 qos 完全一致；坏帧不改变 FDB、风暴/迁移队列与出口队列，仍按帧
    计入每帧开销。累计等于上限合法，首次超过即抛 QosWorkLimit。
    """
    window = storm["window"]
    limits = storm["limits"]
    move_limit = storm["move_limit"]
    hold = storm["hold"]
    qos_map = qos["map"]
    cap = qos["cap"]
    sched_mode = qos["mode"]
    weights = qos["weights"]
    drop_mode = qos["drop"]
